    "vietnameseMeaning": "What will Send It Right most likely do on August 31?",
    "isPassageQuestion": true,
    "passageInfo": {
      "id": "docs2_p7_p2",
      "title": "Đoạn 2 (Q149-150): Thông báo di dời địa điểm - Trung tâm chuyển phát Send It Right",
      "content": "Notice of New Location\nAs of August 31, the Send It Right packing and shipping center will no longer be located at\nthis site. While we have enjoyed serving customers at this location situated inside the Jovan\nFinancial Building, we have grown beyond the space we have. On September 1, you will find\nSend It Right across Centerville Highway in the Perkins Plaza, Suite 112. Our regular hours\nof 7 A.м. to 10 P.M. from Monday through Friday will resume on that date.\nSend It Right will have a much larger space that was specifically designed for our needs,\nincluding a new self-packing zone for our customers who prefer to bring in their items and\nboxes from home and do their packaging on site. Customers can also purchase our boxes,\noffered in various sizes and shapes. We'll supply the tape, scissors, and worktable.\nWe will continue to offer all the same services as before, but will assist you more quickly as\nthe additional space will allow us to hire more employees to work during peak hours. As a\nreminder, our services include packing, shipping, mailing, faxing, and notarizing items as well\nas renting an expanded selection of individual mailboxes. We will continue to offer both\ndomestic and international courier services, and will send packages or documents through\nour regular shipping services as well. We hope you continue to do business at our new\nlocation.",
      "vietnameseTranslation": "Thông báo về Địa điểm Mới\n\nKể từ ngày 31 tháng 8, trung tâm đóng gói và vận chuyển Send It Right sẽ không còn đặt tại địa điểm này nữa. Mặc dù chúng tôi rất hân hạnh được phục vụ khách hàng tại địa điểm nằm bên trong Tòa nhà Tài chính Jovan này, nhưng quy mô của chúng tôi đã vượt quá không gian hiện có. Vào ngày 1 tháng 9, bạn sẽ tìm thấy Send It Right ở bên kia Xa lộ Centerville tại TTTM Perkins Plaza, Phòng 112. Giờ làm việc bình thường từ 7 giờ sáng đến 10 giờ tối từ thứ Hai đến thứ Sáu sẽ tiếp tục vào ngày hôm đó.\nSend It Right sẽ có không gian lớn hơn nhiều được thiết kế riêng cho nhu cầu của chúng tôi, bao gồm một khu vực tự đóng gói mới dành cho những khách hàng thích mang đồ đạc và hộp từ nhà đến và tự đóng gói tại chỗ. Khách hàng cũng có thể mua các loại hộp của chúng tôi, được cung cấp với nhiều kích cỡ và hình dạng khác nhau. Chúng tôi sẽ cung cấp băng dính, kéo và bàn làm việc. Chúng tôi sẽ tiếp tục cung cấp tất cả các dịch vụ như trước đây, nhưng sẽ hỗ trợ quý khách nhanh chóng hơn vì không gian bổ sung sẽ cho phép chúng tôi thuê thêm nhân viên làm việc trong giờ cao điểm.",
      "clues": []
    },
