      "content": "Sandra Fuller\n[2:23]\nThank you again for planning such a good client visit with\nthe representatives from IPD Toy Incorporated. I'm quite\nimpressed.\nBrent Cavanaugh\n[2:25)\nI'm glad to hear that. They seemed interested in placing an\norder for some of the toy lines that I described during my\npresentation.\nSandra Fuller\n[2:27]\nOh, didn't you know? They contacted us this morning to say\nthey have decided to carry our Happy Abbey Doll line in all\ntheir stores globally.\nSandra Fuller\n[2:28]\nThey think that there may be a market for the dolls and have\nagreed to order 500 units to start.\nBrent Cavanaugh\n[2:29]\nThat's great! This could really help us establish our brand\ninternationally.\nTEST\n8",
