    "passageInfo": {
      "id": "docs2_p7_p4",
      "title": "Đoạn 4 (Q153-154): Email đặt chỗ - Đổi lịch cuộc họp và bữa trưa công ty",
      "content": "To:\nFrom:\nDate:\nKay Fine <kay.fine@beebonnethall.com>\nJoe Warner <joe.warner@sammonsproductions.com>\nNovember 17\nSubjects: Sammons Productions booking change\nDear Ms. Fine,\nLast month, I booked your facility to host our company's upcoming employee meeting and\nluncheon on January 30. Unfortunately, I have just learned that our president will be out of\nthe country on that date. So, I would like to reschedule for the following week, if possible. My.\nfirst choice of date is February 5 at the same time as before, 12 p.M. Please notify me as soon\nas possible if you have the space available. If not, let me know what dates are free.\nAlso, you provided a selection of menu options for the luncheon, and I have had some time to\nlook through them. I would like to choose the grilled chicken along with spring pasta and\ntossed salad for the main course. For dessert, I will go ahead and select your cherry\ncheesecake. Also, I forgot to ask you about what types of beverages are offered, and I don't\nsee them on the list of menu options. Could you send me information regarding the options as\nwell?\nFeel free to reply to this e-mail or, if you prefer, you may call me at 555-6758. I look forward\nto hearing from you shortly.\nSincerely,\nJoe Warner",
      "vietnameseTranslation": "Gửi: Kay Fine <kay.fine@beebonnethall.com>\nTừ: Joe Warner <joe.warner@sammonsproductions.com>\nNgày: 17 tháng 11\nTiêu đề: Thay đổi đặt chỗ của Sammons Productions\n\nKính gửi bà Fine,\nTháng trước, tôi đã đặt cơ sở của bà để tổ chức cuộc họp nhân viên và bữa tiệc trưa sắp tới của công ty chúng tôi vào ngày 30 tháng 1. Thật không may, tôi vừa biết rằng chủ tịch của chúng tôi sẽ đi công tác nước ngoài vào ngày hôm đó. Vì vậy, tôi muốn đổi lịch sang tuần sau, nếu có thể. Lựa chọn ngày đầu tiên của tôi là ngày 5 tháng 2 vào cùng khung giờ như trước, 12 giờ trưa. Xin vui lòng thông báo cho tôi sớm nhất có thể nếu bà còn chỗ trống. Nếu không, xin vui lòng cho tôi biết những ngày nào còn trống.\nNgoài ra, bà đã cung cấp danh sách các lựa chọn thực đơn cho bữa tiệc trưa và tôi đã có thời gian xem qua. Tôi muốn chọn món gà nướng cùng với mì ống mùa xuân và salad trộn cho món chính. Đối với món tráng miệng, tôi sẽ chọn bánh pho mát anh đào của bà. Ngoài ra, tôi quên hỏi bà về các loại đồ uống được cung cấp và tôi không thấy chúng trong danh sách thực đơn. Bà có thể gửi cho tôi thông tin về các lựa chọn đồ uống này được không?",
      "clues": []
    },
