      "id": "docs2_p7_p5",
      "title": "Đoạn 5 (Q155-157): Hướng dẫn sử dụng - Máy tập thể dục Flextone 900",
      "content": "Important Information Regarding the Flextone 900\nPlease read the enclosed user's manual before assembling the product. Morcover, retain these\ninstructions for future reference. Do not use the product if any parts are missing. Contact us at\nthe number provided to have any missing parts shipped to you.\nBefore each use, check that all pieces are securely fastened. You risk serious injury if the machine\nhas not been attached correctly. Components may come loose after an extended period of use, so\nit is vital that you regularly check that everything is in order and make repairs as necessary.\nCaution:\n1. Always consult a qualified doctor before undertaking any exercise program. Excessive or\nincorrect training on this apparatus may cause injury.\n2. Make sure the equipment rests on a flat surface and that all bolts, pins, and fasteners are secure\nbefore beginning your workout.\n3. Wear suitable clothing when using the product. Avoid loose attire and jewelry of any kind, as\nsuch items may catch when exercising with this equipment.\n4. Ensure there is enough clearance around the machine to permit unrestricted use.\n5. At no time should young children be allowed access to the machine, even when it is not in use.\nFor general care and maintenance, wipe upholstered surfaces with a warm, damp cloth. Do not\nuse the Flextone 900 if signs of damage are present.",
      "vietnameseTranslation": "Flextone 900\n\nVui lòng đọc kỹ hướng dẫn sử dụng kèm theo trước khi lắp ráp sản phẩm. Hơn nữa, hãy giữ lại các hướng dẫn này để tham khảo trong tương lai. Không sử dụng sản phẩm nếu thiếu bất kỳ bộ phận nào. Liên hệ với chúng tôi theo số điện thoại được cung cấp để các bộ phận bị thiếu được chuyển đến bạn.\nTrước mỗi lần sử dụng, hãy kiểm tra xem tất cả các bộ phận đã được gắn chặt chưa. Bạn có nguy cơ bị thương tích nghiêm trọng nếu máy không được lắp ráp đúng cách. Các bộ phận có thể bị lỏng sau một thời gian dài sử dụng, vì vậy điều quan trọng là bạn phải thường xuyên kiểm tra xem mọi thứ có ổn định không và sửa chữa khi cần thiết.\nLưu ý cảnh báo:\n1. Luôn tham khảo ý kiến bác sĩ có chuyên môn trước khi thực hiện bất kỳ chương trình tập thể dục nào.\n2. Thiết bị này không dành cho trẻ em dưới 12 tuổi sử dụng.\n3. Chỉ sử dụng các bộ phận thay thế chính hãng của nhà sản xuất.",
