      "content": "& Blake Dunlap\n10:28 A.M. Hi, everyone. I'm happy to announce that Alstrop's board of directors\nhas decided to open a sixth branch in Cleveland. Consequently, they'd\nlike to transfer existing employees so that the branch is launched as\nquickly as possible. In fact, I need each of you to submit some staffing\nrecommendations.\nCathy Schultz\n10:30 A.M. Would the transfers be temporary? Many of our staff members have\nlived here in Inglewood their entire lives. They won't be happy about\nthis.\n© Blake Dunlap\n10:31 A.M. That will depend on the preference of each employee. Naturally,\nperformance is also a factor.\nRoy Reese\n® Blake Dunlap\n10:31 л.м. When's our target opening date?\n10:32 A.M. The branch must be fully operational by November 15 to take\nadvantage of our year-end tire sale.\nGeorge Kesterson 10:32 л.м. If you're looking for an office administrator, I think Tammy Roselli\nwould do a great job. She does have a family here though, so I'm\nunsure if she'd want to move.\nRoy Reese\nBlake Dunlap\n10:34 A.M. And for sales director, Charles Kang would be a good choice.\n10:36 A.M. Great suggestions! Any ideas for a purchasing clerk? We will need\nsomeone to start ordering merchandise right away.\nCathy Schultz\n10:38 A.м1. What about Carson Drake? He's been working in the same position\nfor years and he needs a challenge.\nBlake Dunlap\n10:40 A.M. That is a good idea. Anyway, there are a number of other roles to fill,\nand I'll forward you all a list later today. Message me or drop by\nhuman resources if you have any other ideas.\nSend",
