      "content": "INVOICE\nClean Genie\n3102 Hamilton Boulevard\nAllentown, PA 18103\n555-7681\nwww.cleangenie.com\nBill to:\nVasco's Bistro\n501 Broad Street, Emmaus, PA 18049\n555-0219\nDate of invoice: August 8\nJob # C6512-2\nDescription of Services\nFully inspected premises and issued a report dated July 24\nDisinfected all surfaces with Clean Genie Surface Wash\nVacuumed carpeting in main dining area and applied Clean Genie Protect\nSanitized air in main dining area with Clean Genie Fresh Burst\nRemoved items marked for disposal\nPerformed follow-up inspection and cleaning on August 1\nIssued laboratory-certified cleanliness report dated August 5\nProvided Lehigh County Association of Food Retailers membership discount\nComments\nClient requested service as part of obligation to meet permit\nrequirements of the Emmaus Borough Department of Food\nSanitation. Additional discounts applied for using Clean Genie\npatented formulations.\nPayment information\nPayment method:\n• Cash\nX Check no.: 201-98942-2\n• Credit card no.:\nPrice\n$9.00\n$24.25\n$23.50\n$18.75\n$14.00\n$12.00\n$25.00\n($15.00)\nSub-total\n$111.50\nAdditional discounts\n($15.00)\nTax\nTOTAL\n$9.00\n$105.50\nCustomer Signature\nSigning your name below indicates your\nacceptance of the job as performed and\nagreement with all charges.\nEvelyn Moore\nEvelyn Moore, supervisor\nTEST | 01",
      "vietnameseTranslation": "HÓA ĐƠN DỊCH VỤ\nClean Genie\n3102 Đại lộ Hamilton, Allentown, PA 18103\nNgày lập hóa đơn: 8 tháng 8 | Mã công việc: # C6512-2\nKhách hàng: Vasco's Bistro, 501 Phố Broad, Emmaus, PA 18049\n\nMô tả dịch vụ:\n- Kiểm tra toàn bộ cơ sở và cấp báo cáo ngày 24 tháng 7: $9.00\n- Khử trùng tất cả các bề mặt bằng dung dịch Clean Genie Surface Wash (sản phẩm độc quyền)\n- Hút bụi thảm phòng ăn chính và phủ chất bảo vệ Clean Genie Protect\n- Khử mùi và làm sạch không khí bằng Clean Genie Fresh Burst\n- Dọn dẹp rác thải và các vật dụng đánh dấu tiêu hủy\n- Kiểm tra và dọn dẹp tiếp theo vào ngày 1 tháng 8\n- Cấp chứng nhận vệ sinh đạt chuẩn phòng thí nghiệm ngày 5 tháng 8\n- Giảm giá thành viên Hiệp hội Bán lẻ Thực phẩm Quận Lehigh: -$15.00\nGhi chú: Khách hàng yêu cầu dịch vụ theo quy định bắt buộc của Phòng Vệ sinh Thực phẩm Emmaus Borough.\nTổng cộng: $105.50\nChữ ký khách hàng: Evelyn Moore, người giám sát (Quản lý tại Vasco's Bistro)",
