      "id": "docs2_p7_p13",
      "title": "Đoạn 13 (Q186-190): Đoạn Ba: Thông báo đào tạo của Dayton Bank, Phiếu đăng ký & Email của Bernard Hinds",
      "content": "Dayton Bank\nDayton Bank regularly subsidizes outside skills development courses for its employees. Beginning April 1,\nPittman Training will once again make the following courses available to us, and these can be taken at the\ntraining facility or online. Employees who complete a course will receive a certificate from Pittman Training.\nCourse,\nDuration\nInstructor/Description\nDays/Time.\nEffective Teller\n3 weeks\nSam Penner: This course will enhance skills in effective\nMon. /Wed./Fri.\nOperations\nteller operations and dealing with customer problems.\n8:30-11:30 A.M.\nThere are no prerequisites.\nBank Employee.\nDevelopment\n2 reeks\nLee Ching: This course focuses on more complex bank\ntransactions, such as international wire transfers.\nParticipants must pass Effective Teller Operations before\ntaking this coutse.\nCredit Risk\nManagement\n1 week\nJean Harker: This course teaches how to minimize risk\nwhen reviewing loan applications. Only those who have\nMon./Wed./Fri.\n8:30-11:30 A.M.\nTues./Thur\n1:30-6:00 P.M.\nMon.-Fri.\n1:00-5:00 P.M.\nworked for Dayton Bank for two years or more are\neligible to enroll in this class.\nFor more information and to register for a course, please visit Pittman Training's Web site at www.\npittmantraining.com.\nwww.pittmantraining.com/registration\nCourse Registration\nPlease fill out the form completely and revlew your Information before clicking on \"Next.\"\n* Name: Bernard Hinds\n* Street Address: 121 Rosemont Avenue, Chicago, Illinois, 60615\n* E-mail address: bernardhinds@smail.com\n* Telephone number: 555-2143\n* Sign me up for the following cours®: Bank Employee Development\n* Preferred schedule: Tues./Thur.\n* Please indicate whether you meet the prerequisite requirement: Yes No N/A (Not Appilcable) •\nPayment Information\nClick Online payment to pay by credit card. If you wish to pay by bank transfer, please note the following\naccount information:\nBank name: First Standard Bank\nAccount Number: 3948-293\nPayments by check should be malled to Pittman Training, 9000 South Emerald Avenue, Chicago, IL\n60620.\nCredit card and bank transfer payments are processed immediately, and your enrollment will be\nconfirmed here after clicking \"Next.\" If you send a check, we will send you an e-mail confirming your\nenrollment within three business days of receiving your payment.\nNext\n256.\nRE 4E9 9038-5078738 33088 123 \n\n\nTo: Pittman Training <inquiries@pittmantraining.com>\nFrom: Bernard Hinds <bernardhinds@smail.com>\nSubject: Follow up\nDate: March 26\nTo Whom It May Concern,\nI would like to follow up on my registration for the Bank Employee Development training course. I submitted\nmy payment one week ago and received an e-mail confirming my enrollment. However, I still haven't received\nthe course syllabus. Please send it to me as soon as possible so that I can begin preparing for the class.\nAlso, a colleague of mine is interested in taking the same course. I realize that it may be too late to register\nsince the deadline has passed, but I am wondering whether an exception can be made if the class isn't already\nfull. Thanks.\nBernard Hinds",
      "vietnameseTranslation": "VĂN BẢN 1: THÔNG BÁO TỪ NGÂN HÀNG DAYTON BANK\nNgân hàng Dayton Bank thường xuyên tài trợ các khóa học phát triển kỹ năng bên ngoài cho nhân viên. Bắt đầu từ ngày 1 tháng 4, Trung tâm Pittman Training sẽ một lần nữa mở các khóa học sau đây cho chúng ta, có thể học tại cơ sở hoặc trực tuyến. Tất cả các khóa học đều cấp chứng chỉ khi hoàn thành.\n1. Nghiệp vụ Giao dịch viên Hiệu quả (3 tuần, T2/T4/T6 8:30-11:30 sáng, không yêu cầu điều kiện tiên quyết).\n2. Phát triển Nhân viên Ngân hàng (2 tuần, T3/T5 1:30-6:00 chiều, điều kiện tiên quyết: phải hoàn thành khóa Nghiệp vụ Giao dịch viên trước khi tham gia).\n3. Quản trị Rủi ro Tín dụng (1 tuần, T2-T6 1:00-5:00 chiều, điều kiện: nhân viên làm việc từ 2 năm trở lên).\n\n--------------------------------------------------\n\nVĂN BẢN 2: PHIẾU ĐĂNG KÝ KHÓA HỌC (PITTMAN TRAINING)\nHọc viên: Bernard Hinds\nĐịa chỉ: 121 Rosemont Avenue, Chicago, Illinois\nKhóa học đăng ký: Phát triển Nhân viên Ngân hàng (Bank Employee Development)\nLịch học lựa chọn: Thứ Ba / Thứ Năm (Tues./Thur.)\nĐáp ứng điều kiện tiên quyết (Prerequisite): Có (Yes) -> Nghĩa là Bernard Hinds đã từng học khóa Nghiệp vụ Giao dịch viên trước đó.\nThanh toán bằng séc gửi qua đường bưu điện tới: Pittman Training, 9000 South Emerald Avenue, Chicago, IL 60620. Đăng ký qua séc sẽ được xác nhận qua email trong vòng 3 ngày làm việc sau khi nhận được séc.\n\n--------------------------------------------------\n\nVĂN BẢN 3: EMAIL CỦA BERNARD HINDS\nGửi: Pittman Training <inquiries@pittmantraining.com>\nNgày: 26 tháng 3\nTôi viết thư để theo dõi việc đăng ký khóa học Phát triển Nhân viên Ngân hàng. Tôi đã gửi thanh toán bằng séc cách đây một tuần và đã nhận được email xác nhận. Tuy nhiên, tôi vẫn chưa nhận được giáo trình môn học. Ngoài ra, một đồng nghiệp của tôi cũng rất muốn đăng ký khóa học này cùng tôi. Dù đã quá hạn chót đăng ký nhưng không biết trung tâm có thể xem xét ngoại lệ nếu lớp còn chỗ trống hay không?",
