      "content": "Vera Advertising\nMEMO\nTo: All staff\nFrom: Joseph Tran, Human resources director\nSubject: Staff retreat\nDate: August 1\nI'd like to remind everyone that our annual staff retreat is coming up. This will take place from August 20\nto 22 at the River Ranch Resort in Holbrook, which is a three-hour drive away. The company has\nrented a bus that leaves Phoenix at 8 a.M. on the 20th. For those of you who cannot make it at that\ntime, Michelle Salazar will pick you up at around 2 p.M. Please contact her to make arrangements.\nWe've planned several activities for this outing, and copies of the agenda have been circulated among\nthe departments. We will be giving everyone the day off on the Monday right after the retreat. If you\nhave any questions, feel free to call me at extension 39.\nVera Advertising Annual Staff Retreat\nRiver Ranch, Holbrook, AZ\nFriday, August 20\n11:00 A.M. Arrive at River Ranch\n12:00 р.м.\nLunch\n2:00 P.M.\nLeisure activity: Horseback riding with a guide\n5:00 P.M.\nTeam building: Improving communication skills\nTeam building: Creative problem solving\n7:00 P.M.\nSaturday, August 21\n8:00 A.M.\nBreakfast\n10:00 A.M.\nSeminar: Embracing innovation\n12:00 P.M.\nLunch\n2:00 P.M.\nLeisure activity: Guided whitewater rafting\n7:00 P.M.\nDinner\n8:30 P.M. Staff meeting: Outlook for the next quarter\nSunday, August 22\n8:00 A.M. Breakfast\n9:00 A.M. Closing remarks from CEO Kent Vera\n10:00 A.M. Group photo\n10:30 A.M. Depart for Phoenix\nNote:\nAll meals will be served in the lunch room located in the main building. All\noutdoor leisure activities are subject to change depending on the weather.\n\n\nTo: Joseph Tran <j.tran@veraadvertising.com>\nFrom: Steven Oliver <s.oliver@holbrookriverranch.com>\nSubject: Re: requests\nDate: August 12\nHi Joseph,\nI'm writing this e-mail to let you know that I carried out all of the requests in your last message. As you\nasked, we booked three double rooms for Vera's top management, and nine other standard rooms for\nthe staff. We have also made sure that vegetarian and gluten-free menu options are available in\naddition to our regular ones. Finally, I asked the kitchen staff to keep the lunch room stocked with hot\nand cold beverages, as well as light refreshments, throughout each day of the retreat. There is one issue\nyou should be aware of, though. The main building will be closed for repainting on Sunday, August 22.\nSo, I recommend that you use the annex for your activities on that day instead. If there is anything\nmore I can do at this time, please let me know. Thank you!\nSteven Oliver\nTEST",
      "vietnameseTranslation": "VĂN BẢN 1: BẢN GHI NHỚ NỘI BỘ VORA ADVERTISING\nTừ: Joseph Tran, Giám đốc Nhân sự\nGửi: Toàn thể nhân viên\nChủ đề: Kỳ nghỉ dưỡng kết hợp tập huấn thường niên của công ty tại Trang trại Holbrook River Ranch từ ngày 15 đến 17 tháng 9. Phương tiện di chuyển: xe buýt công ty sẽ đón tại trụ sở lúc 8:00 sáng. Bà Salazar đã tình nguyện sử dụng xe cá nhân chở một số thiết bị âm thanh và tài liệu tập huấn.\n\n--------------------------------------------------\n\nVĂN BẢN 2: LỊCH TRÌNH HOẠT ĐỘNG DỰ KIẾN\n- Ngày 1: Nhận phòng, họp định hướng, ăn trưa, hội thảo kỹ năng sáng tạo quảng cáo, ăn tối BBQ ngoài trời.\n- Ngày 2: Bữa sáng, hoạt động trải nghiệm dã ngoại có hướng dẫn (chèo thuyền kayak và cưỡi ngựa - guided leisure activity), nghỉ trưa, trò chơi xây dựng đội ngũ, tiệc tối gala.\n- Ngày 3: Bữa sáng, chụp ảnh lưu niệm toàn công ty, hoạt động dã ngoại có hướng dẫn (đi bộ xuyên rừng - guided leisure activity), phát biểu bế mạc của Tổng Giám đốc, lên xe về thành phố lúc 3:00 chiều.\n\n--------------------------------------------------\n\nVĂN BẢN 3: EMAIL TỪ STEVEN OLIVER (HOLBROOK RIVER RANCH)\nGửi: Joseph Tran <j.tran@voraadvertising.com>\nNgày: 12 tháng 8\nChào Joseph, chúng tôi đã nhận được các yêu cầu chuẩn bị của bạn. Chúng tôi hoàn toàn có thể đáp ứng thực đơn ăn kiêng và ăn chay theo các sở thích khác nhau của nhân viên bạn. Chúng tôi cũng đã bố trí phòng riêng theo danh sách bạn gửi. Tuy nhiên, về phòng hội trường phụ (annex), chúng tôi hiện chưa có đủ bàn ghế theo yêu cầu vì đang có một đoàn khác sử dụng. Tôi gợi ý bạn nên ăn sáng tại nhà hàng chính của trang trại thay vì yêu cầu phục vụ đồ ăn tại khu nhà nghỉ.",
