    "explanation": "Đối chiếu thông tin trong bài văn đoạn 15. Đáp án chính xác được xác nhận từ đáp án chuẩn của bài thi là (D): 'It is opening a branch at an airport terminal.'.",
    "tip": "⚡ MẸO PART 7: Quét từ khóa trong câu hỏi 'What is NOT mentioned about Botwell's ne...' để định vị đoạn chứa thông tin tương ứng trong văn bản.",
