    "vietnameseMeaning": "What is NOT mentioned about Botwell's new establishment?",
    "isPassageQuestion": true,
    "passageInfo": {
      "id": "docs2_p7_p15",
      "title": "Đoạn 15 (Q196-200): Đoạn Ba: Trang web cửa hàng miễn thuế Botwell, Thông báo nội bộ & Hóa đơn của Emilia Fortich",
      "content": "http://www.botwellstore.com/news/dutyfree\nHOME CONTACT MEMBERSHIP\nI PROMOTIONS |\nHOURS/LOCATION\nNEWS\nComing Soon ... Duty-Free Shopping at Botwell Department Store\nBotwell Department Store, situated in the heart of Cape Town, is pleased to announce that on April 12 it\nwill be opening a new duty-free store designed for all international travelers. Located on Botwell's fifth\nfloor, the establishment will feature luxury goods such as cosmetics, perfumes, liquors, jewelry, and\nmore. In celebration of the opening, all items by Moreno Luggage and Lydia Cosmetics will be marked\ndown by 20 percent until May 15. To buy any product being sold in the duty-free store, customers will\nneed to provide a passport and a ticket that will be used for an international departure within 28 days.\nThose who are members of the Botwell Frequent Shopper program can receive an additional 10 percent\noff all duty-free products.\nBOTWELL DEPARTMENT STORE\nI'm very grateful to everyone for helping to make the first week of our duty-free store a success.\nOverall, I am pleased with your efforts and with how well the store ran. However, there are a few\nimportant things to take note of.\nFirst, I received a number of complaints about our voucher program. Please recall that it is our\npolicy to give vouchers to customers who make purchases totaling $500 or more. These vouchers\nallow them to take advantage of discounts on our partner establishments' Web sites. Please\nremember to give one to every eligible customer.\nSecond, if a member of our frequent shopper program has lost his or her card, we cannot offer the\nreduced price. However, shoppers may keep their receipts and get reimbursed for the difference\nonce the card has been located or replaced\nThank you for your attention to these matters, and keep up the good work.\nBotwell Department Store Receipt\nIssued: April 19\nTo: Emilia Fortich\nCitizenship: Spanish\nPassport number: XCV81324\nFlight: Vela Airways VI342\nDate of departure: April 21\nItem\nRiley leather handbag (plum)\nLydia Cosmetics lipstick\nLeganz digital camera\nDaphne Boutique scarf\nDestination: Madrid, Spain\nQuantity\n1\n1\n1\n1\nTOTAL\nPrice\n$160.00\n$46.00\n$258.00\n$62.00\n$526.00\n260 RE 2204592924-508718 990871MP3 \n\n\nPlease note:\nCape Town Airport Authority (CTAA) regulations prohibit the transport of\nmore than 100 milliliters of liquids and gels onboard unless the products\nhave been purchased at a duty-free store and secured in a plastic bag\nbearing the official CTAA seal. Furthermore, note that such items must be\nremoved from luggage when passing through a security checkpoint.",
      "vietnameseTranslation": "VĂN BẢN 1: TRANG WEB CỬA HÀNG BÁCH HÓA BOTWELL\nSắp Khai Trương ... Mua Sắm Miễn Thuế tại Trung Tâm Bách Hóa Botwell\nTọa lạc tại trung tâm Cape Town, Cửa hàng Bách hóa Botwell vui mừng thông báo vào ngày 12 tháng 4 sẽ khai trương cửa hàng miễn thuế mới dành cho tất cả du khách quốc tế trên tầng 5 của tòa nhà bách hóa. Cửa hàng cung cấp các mặt hàng cao cấp như mỹ phẩm, nước hoa, rượu, trang sức. Nhân dịp khai trương, tất cả các sản phẩm của Moreno Luggage và Lydia Cosmetics sẽ được giảm giá 20% cho đến ngày 15 tháng 5. Khách hàng cần xuất trình hộ chiếu và vé máy bay quốc tế khởi hành trong vòng 28 ngày. Thành viên chương trình Khách hàng Thân thiết Botwell sẽ được giảm thêm 10%.\n\n--------------------------------------------------\n\nVĂN BẢN 2: THÔNG BÁO NỘI BỘ GỬI NHÂN VIÊN THU NGÂN\nTôi rất cảm ơn mọi người đã giúp tuần khai trương đầu tiên của cửa hàng miễn thuế thành công tốt đẹp. Tuy nhiên, xin lưu ý hai điều quan trọng:\nThứ nhất, chính sách của chúng tôi là tặng phiếu ưu đãi mua sắm (voucher) cho tất cả khách hàng có hóa đơn mua hàng từ $500 trở lên để sử dụng trên các trang web đối tác. Xin hãy nhớ trao phiếu này cho mọi khách hàng đủ điều kiện.\nThứ hai, nếu thành viên khách hàng thân thiết quên hoặc làm mất thẻ, chúng ta không thể áp dụng giá giảm ngay lúc thanh toán. Tuy nhiên, họ có thể giữ lại hóa đơn để được hoàn lại tiền chênh lệch sau khi tìm lại hoặc được cấp lại thẻ mới.\nLưu ý an ninh sân bay (CTAA): Du khách chỉ được phép mang chất lỏng/gel trên 100ml lên máy bay nếu mua tại cửa hàng miễn thuế và được bọc kín (enclosed/secured) trong túi nhựa có niêm phong chính thức của CTAA.\n\n--------------------------------------------------\n\nVĂN BẢN 3: HÓA ĐƠN MUA HÀNG CỦA EMILIA FORTICH\nNgày phát hành: 19 tháng 4\nKhách hàng: Emilia Fortich | Quốc tịch: Tây Ban Nha | Hộ chiếu: XCV81324\nChuyến bay: Vela Airways VI342 | Ngày bay: 21 tháng 4 | Điểm đến: Madrid, Tây Ban Nha\nDanh mục hàng mua:\n1. Túi xách da Riley (màu mận): $160.00\n2. Son môi Lydia Cosmetics (được giảm giá 20% theo chương trình khai trương): $46.00\n3. Máy ảnh kỹ thuật số Leganz: $258.00\n4. Khăn quàng cổ Daphne Boutique: $62.00\nTỔNG HÓA ĐƠN: $526.00 (Đạt trên $500 -> đủ điều kiện nhận voucher mua sắm đối tác).",
      "clues": []
    },
