      "title": "YBM Part 7: Bài đọc 12 (Q181-Q185)",
      "content": "Majestic Travel: Customer Invoice #8394\nCustomer: Kasis Rizal\nBooking Date: May 3\nDestination: Palm Island\nFirst-Time Visitor: Yes\nAccommodation: Hibiscus Corporation\nRoom Type: Deluxe\nNumber of Adults: 2, Number of Children: 0\n$700.00\nCheck in: July 19 / Check out: July 23\nDining: Villa Complex\nAll-Day Meal Pass, 2 Adults: July 20-22\n$185.00\nBreakfast Meal Pass, 2 Adults: July 23\nActivity 1: Meridian Limited\nPrivate Boat Tour of Meridian Cove: July 21\n$390.00\nDeposit of $100 received on May 3\nActivity 2: Orchid Enterprises\nWorkshop: How to Prepare Regional Cuisine,\n$60.00\n2 Adults: July 22\nSubtotal\nRemaining due\n$1,335.00\n$1,235.00\nNote: Plane tickets to be booked separately by the customer.\n*E-mail*\nKasis Rizal <krizal@stiles-inc.net>\nRaja Tahyadi <tahyadiraja@majestictravel.com>\nMay 8\nRE: Inquiry\nTo:\nFrom:\nDate:\nSubject:\nDear Ms. Rizal,\nIn response to your inquiry, I double-checked your invoice #8394), and I can confirm that\neverything on the invoice is correct. I believe the source of confusion is that the price for\nthe boat tour listed on our Web site is just a base fee, but a booking charge and additional\nvalued added tax (VAT) were also applied, resulting in the total you see on the invoice.\nThis was explained at the bottom of the booking page. Additionally, you are getting a\ndiscount on your meal passes because we are partners with that business, so the overall\nprice of the vacation is quite reasonable. Nevertheless, if you would like to cancel the boat\ntour, you may do so, but the request must be made in writing by May 31, and you would\nlose half of your deposit. If you cancel after this date, you will be charged the full amount.\nAttached you will find the instructions once again for paying the remaining balance by\nbank transfer. As I mentioned when you booked the trip, we no longer accept cash, checks,\nI hope I have answered your questions to your satisfaction, but please do not hesitate to\ncontact me if you have further inquiries.\nWarmest regards,\nRaja Tahyadi\nMajestic Travel\n26",
