      "content": "Viola Dalton\n528 Coleman Road\nCharlotte, NC 28210\nJuly 6\nDear Ms. Dalton,\nIt was a pleasure to meet you at your interview on June 13. The entire\nhiring committee was impressed with your career history as well as your\nnatural people skills. We are pleased that you have accepted the position of\nR&D Department Manager. Now that we have both signed the contract, it\nis official. Enclosed you will find a copy of the contract for your records.\nFor the orientation on July 17, you will be assigned to Group C. I look\nforward to seeing you there!\nSincerely,\nArina Saitou\nArina Saitou\nHR Manager, Caldwell Corporation\nTo:\nFrom:\nDate:\nSubject:\nUndisclosed Recipients\nArina Saitou\nJuly 13\nOrientation at the Caldwell Corporation\nDear New Employees,\nAs we have just moved into our headquarters building, most of you have not seen it yet.\nThe building has a spacious patio area for taking breaks or eating lunch outside, and the\nLansing River runs right past it, so the views are amazing. I'm sure you will love it as much\nas the rest of the staff does.\n› expedite the check-in process at the orientation on July 17, employees of ea\npartment should report to different rooms. Please see the table belo\nDepartments)\nRoom\nGraphic Design\nRoom 308\nResearch & Development, Accounting\nRoom 233\nMarketing, Sales\nConference Room A\nAdministration, Human Resources\nConference Room B\nI have attached a copy of the orientation schedule. Please do not hesitate to contact me with\nany questions you may have.\nSincerely,\nArina Saitou\nHR Manager, Caldwell Corporation\n30\n\n\n8:30 A.M.\n9:00 A.M.\n9:30 A.M.\n11:45 A.M.\n12:15 P.M.\n1:15 P.M.\n2:30 P.M.\n4:45 P.M.\nGaldwell Corporation\nStaff Orientation, July 17\nCheck-in (report to assigned rooms)\nWelcome speech, CEO Yan Huo\nTax Paperwork and Vacation Policies, Ruth Bova\nDress Code, Hamid Yemane\nLunch: During the lunch break, groups should visit the security\noffice to be assigned ID badges according to the following\nschedule: Group A 12:15 P.M., Group B 12:30 P.M., Group C 12:45\nP.M., Group D 1:00 P.M.\nOnline Activities from Work Computers, Jocelyn Lewis\nSplit Session: Managers will hear a talk from Director Diego\nBarros, non-management full-time employees will have a\nquestion-and-answer session with Prabha Haldar, and part-time\nemployees will watch a training video\nBuilding tour, Arina Saitou",
