      "content": "Are you sick of the choices offered by restaurants? Now, there is another ---[139]--- that has become a trend from London to Peru: the underground gourmet clubs. As the name suggests, these dining places are in private properties, and meals are prepared by food lovers or chefs who are between jobs.\nPeople who are interested in having a taste can check out the social networking websites, such as Facebook or Twitter ---[140]--- out what most gourmets recommend. These privately run restaurants will put the menus of the day online, most of which are experimental dishes or homemade specialties. Consequently, the diners will get to taste something they have never tried in typical restaurants.\nAlso, the atmosphere in these dining clubs ---[141]--- gets too formal or stiff because the settings help diners to strike up conversations easily. ---[142]--- Surprisingly, the diners will only be informed of a recommended donation price, which is approximately the same as a regular meal in an ordinary restaurant.",
